28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
41	    private static final Map<String, String> CITY_REGION = Map.of(
42	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
43	
44	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
45	     *  {@link #getLocality()} in preference to the city. */
46	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
47	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
48	
49	    @Column(name = "address")
50	    @NotEmpty
51	    private String address;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "membership_number")
82	    private String membershipNumber;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "household_size")
88	    private Integer householdSize;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    /**
110	     * The owner's locality, i.e. the canonical region it belongs to. This is now read
111	     * from the region-and-hash {@link #customerCode} identity: the region is the
112	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
113	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
114	     * been assigned a customer code (for example while its create request is still
115	     * being validated) this falls back to the region derived directly from its own
116	     * fields (see {@link #regionForOwner()}). Exposed as a derived (not persisted)
117	     * property and recomputed each call.
118	     *
119	     * @return the canonical region string, or {@code "UNKNOWN"}
120	     */
121	    @Transient
122	    public String getLocality() {
123	        if (this.customerCode != null) {
124	            int dash = this.customerCode.indexOf('-');
125	            if (dash >= 0) {
126	                return this.customerCode.substring(0, dash);
127	            }
128	        }
129	        return regionForOwner();
130	    }
131	
132	    /**
133	     * The canonical region derived for this owner from its own fields. The
134	     * {@link #postcode} is consulted first: when it is present and falls within a known
135	     * region's inclusive 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
136	     * {@code QLD 4000-4099}) that region is returned. Only when the postcode is absent
137	     * or in no known range does this fall back to the fixed city-to-region table
138	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
139	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
140	     * the same region for the known cities while disambiguating cities that share a name
141	     * via their postcode. Recomputed from the current fields each call.
142	     *
143	     * @return the canonical region string, or {@code "UNKNOWN"}
144	     */
145	    public String regionForOwner() {
146	        String byPostcode = regionForPostcode(this.postcode);
147	        if (byPostcode != null) {
148	            return byPostcode;
149	        }
150	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
151	    }
152	
153	    /**
154	     * The region whose inclusive postcode range contains the given postcode, or
155	     * {@code null} when the postcode is absent, not a four-digit number, or in no
156	     * known range.
157	     */
158	    private static String regionForPostcode(String postcode) {
159	        if (postcode == null || !postcode.matches("\\d{4}")) {
160	            return null;
161	        }
162	        int value = Integer.parseInt(postcode);
163	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
164	            int[] range = entry.getValue();
165	            if (value >= range[0] && value <= range[1]) {
166	                return entry.getKey();
167	            }
168	        }
169	        return null;
170	    }
171	
172	    /**
173	     * The owner's membership level, a number from 1 to 3 assigned at creation:
174	     * starting at 1, add 1 when an {@link #email} is present and add 1 when
175	     * {@link #namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
176	     * Derived (not persisted); recomputed from the current fields each call.
177	     *
178	     * @return the membership level, from 1 to 3
179	     */
180	    @Transient
181	    public Integer getMembershipLevel() {
182	        int level = 1;
183	        if (this.email != null && !this.email.isBlank()) {
184	            level++;
185	        }
186	        if (this.namesakeCount != null && this.namesakeCount == 0) {
187	            level++;
188	        }
189	        return Math.min(level, 3);
190	    }
191	
192	    /**
193	     * The owner's preferred contact channel: {@code "EMAIL"} when an
194	     * {@link #email} is present, otherwise {@code "PHONE"}. Derived (not
195	     * persisted); recomputed from the current fields each call.
196	     *
197	     * @return {@code "EMAIL"} or {@code "PHONE"}
198	     */
199	    @Transient
200	    public String getContactPreference() {
201	        if (this.email != null && !this.email.isBlank()) {
202	            return "EMAIL";
203	        }
204	        return "PHONE";
205	    }
206	
207	    public String getTelephone() {
208	        return this.telephone;
209	    }
210	
211	    public void setTelephone(String telephone) {
212	        this.telephone = telephone;
213	    }
214	
215	    public String getEmail() {
216	        return this.email;
217	    }
218	
219	    public void setEmail(String email) {
220	        this.email = email;
221	    }
222	
223	    public String getPostcode() {
224	        return this.postcode;
225	    }
226	
227	    public void setPostcode(String postcode) {
228	        this.postcode = postcode;
229	    }
230	
231	    public LocalDate getRegistrationDate() {
232	        return this.registrationDate;
233	    }
234	
235	    public void setRegistrationDate(LocalDate registrationDate) {
236	        this.registrationDate = registrationDate;
237	    }
238	
239	    public String getCustomerCode() {
240	        return this.customerCode;
241	    }
242	
243	    public void setCustomerCode(String customerCode) {
244	        this.customerCode = customerCode;
245	    }
246	
247	    /**
248	     * The Luhn check digit (0-9) computed over the decimal digits contained in this
249	     * owner's {@link #customerCode}. Derived (not persisted); recomputed from the
250	     * current customer code each call. An absent or digit-free customer code yields
251	     * {@code 0}.
252	     *
253	     * @return the Luhn check digit, from 0 to 9
254	     */
255	    @Transient
256	    public Integer getCheckDigit() {
257	        return luhnCheckDigit(this.customerCode);
258	    }
259	
260	    /**
261	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
262	     * given value, processed right-to-left with every second digit doubled (and
263	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and
264	     * an absent or digit-free value yields {@code 0}.
265	     */
266	    private static int luhnCheckDigit(String value) {
267	        int sum = 0;
268	        boolean doubleDigit = true;
269	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
270	            char c = value.charAt(i);
271	            if (c < '0' || c > '9') {
272	                continue;
273	            }
274	            int d = c - '0';
275	            if (doubleDigit) {
276	                d *= 2;
277	                if (d > 9) {
278	                    d -= 9;
279	                }
280	            }
281	            sum += d;
282	            doubleDigit = !doubleDigit;
283	        }
284	        return (10 - (sum % 10)) % 10;
285	    }
286	
287	    public String getHouseholdId() {
288	        return this.householdId;
289	    }
290	
291	    public void setHouseholdId(String householdId) {
292	        this.householdId = householdId;
293	    }
294	
295	    public Integer getNamesakeCount() {
296	        return this.namesakeCount;
297	    }
298	
299	    public void setNamesakeCount(Integer namesakeCount) {
300	        this.namesakeCount = namesakeCount;
301	    }
302	
303	    public String getMembershipNumber() {
304	        return this.membershipNumber;
305	    }
306	
307	    public void setMembershipNumber(String membershipNumber) {
308	        this.membershipNumber = membershipNumber;
309	    }
310	
311	    public Boolean getBulkSignupWarning() {
312	        return this.bulkSignupWarning;
313	    }
314	
315	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
316	        this.bulkSignupWarning = bulkSignupWarning;
317	    }
318	
319	    public Integer getHouseholdSize() {
320	        return this.householdSize;
321	    }
322	
323	    public void setHouseholdSize(Integer householdSize) {
324	        this.householdSize = householdSize;
325	    }
326	
327	    /**
328	     * The single derived key used for duplicate detection, formed as
329	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
330	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
331	     * is the stored (lower-cased) email or the empty string when absent, and the
332	     * household component is the stored {@link #householdId} or the empty string
333	     * when the owner belongs to no household. Two owners are duplicates of each
334	     * other exactly when their whole identity keys are equal; because the telephone
335	     * is part of the key, two members of the same household with different
336	     * telephones have different identity keys. Derived (not persisted); recomputed
337	     * from the current fields each call.
338	     *
339	     * @return the owner's identity key
340	     */
341	    @Transient
342	    public String getIdentityKey() {
343	        String tel = this.telephone == null ? "" : this.telephone;
344	        String mail = this.email == null ? "" : this.email;
345	        String household = this.householdId == null ? "" : this.householdId;
346	        return tel + "|" + mail + "|" + household;
347	    }
348	
349	    /**
350	     * A stable, normalised key identifying this owner's household (same last name
351	     * and address). The last name is folded case- and whitespace-insensitively and
352	     * the address is reduced to its canonical form exactly as in
353	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
354	     * household.
355	     *
356	     * @return the household key
357	     */
358	    public String householdKey() {
359	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
360	    }
361	
362	    /**
363	     * Whether this owner belongs to the same household as {@code other}: that is,
364	     * they share the same last name and address. The last name is compared
365	     * case-insensitively with runs of whitespace collapsed to a single space (and
366	     * surrounding whitespace trimmed); the address is compared in its canonical
367	     * normalised form (see {@link #normalizeAddress(String)}).
368	     *
369	     * @param other the owner to compare against
370	     * @return {@code true} if both owners share a household
371	     */
372	    public boolean sameHouseholdAs(Owner other) {
373	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
374	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
375	    }
376	
377	    /**
378	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
379	     * trim, collapse internal runs of whitespace to a single space and lower-case.
380	     */
381	    private static String normalize(String value) {
382	        if (value == null) {
383	            return "";
384	        }
385	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
386	    }
387	
388	    /**
389	     * Reduce an address to its canonical stored form: trim and collapse runs of
390	     * whitespace to a single space, upper-case, and expand common abbreviations
391	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
392	     * they appear as whole words. The result is what is stored, returned and used
393	     * for every household comparison; it is idempotent, so re-normalising an
394	     * already-normalised address leaves it unchanged.
395	     *
396	     * @param value the raw address (may be {@code null})
397	     * @return the normalised address, or the empty string if {@code value} is
398	     *         {@code null} or blank
399	     */
400	    public static String normalizeAddress(String value) {
401	        if (value == null) {
402	            return "";
403	        }
404	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
405	        if (collapsed.isEmpty()) {
406	            return "";
407	        }
408	        String[] tokens = collapsed.split(" ");
409	        for (int i = 0; i < tokens.length; i++) {
410	            tokens[i] = switch (tokens[i]) {
411	                case "ST" -> "STREET";
412	                case "RD" -> "ROAD";
413	                case "AVE" -> "AVENUE";
414	                default -> tokens[i];
415	            };
416	        }
417	        return String.join(" ", tokens);
418	    }
419	
420	    protected Set<Pet> getPetsInternal() {
421	        if (this.pets == null) {
422	            this.pets = new HashSet<>();
423	        }
424	        return this.pets;
425	    }
426	
427	    protected void setPetsInternal(Set<Pet> pets) {
428	        this.pets = pets;
429	    }
430	
431	    public List<Pet> getPets() {
432	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
433	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
434	        return Collections.unmodifiableList(sortedPets);
435	    }
436	
437	    public void setPets(List<Pet> pets) {
438	        this.pets = new HashSet<>(pets);
439	    }
440	
441	    public void addPet(Pet pet) {
442	        getPetsInternal().add(pet);
443	        pet.setOwner(this);
444	    }
445	
446	    /**
447	     * Return the Pet with the given name, or null if none found for this Owner.
448	     *
449	     * @param name to test
450	     * @return true if pet name is already in use
451	     */
452	    public Pet getPet(String name) {
453	        return getPet(name, false);
454	    }
455	
456	    /**
457	     * Return the Pet with the given name, or null if none found for this Owner.
458	     *
459	     * @param name to test
460	     * @return true if pet name is already in use
461	     */
462	    public Pet getPet(String name, boolean ignoreNew) {
463	        name = name.toLowerCase();
464	        for (Pet pet : getPetsInternal()) {
465	            if (!ignoreNew || !pet.isNew()) {
466	                String compName = pet.getName();
467	                compName = compName.toLowerCase();
468	                if (compName.equals(name)) {
469	                    return pet;
470	                }
471	            }
472	        }
473	        return null;
474	    }
475	
476	    public Pet getPet(Integer petId) {
477	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
478	    }
479	
480	    @Override
481	    public String toString() {
482	        return new ToStringCreator(this)
483	
484	            .append("id", this.getId())
485	            .append("new", this.isNew())
486	            .append("lastName", this.getLastName())
487	            .append("firstName", this.getFirstName())
488	            .append("address", this.address)
489	            .append("city", this.city)
490	            .append("telephone", this.telephone)
491	            .toString();
492	    }
493	}
